/** PROCEDURE DIVISION USING W77-SISTEMA-PARAM: se recibe como JobParameter. */
@ConfigurationProperties("p107")
public record P107Properties(Map<String, PerfilSistema> sistemas) {

    public record PerfilSistema(int interlocutor, Integer servicio, Integer servicio600,
                                char nomenclatura) {}

    public PerfilSistema perfil(int sistemaParam) {
        return sistemas.getOrDefault(String.valueOf(sistemaParam), sistemas.get("default"));
    }
}

@Bean @StepScope
PerfilSistema perfilSistema(P107Properties props,
                            @Value("#{jobParameters['sistema']}") Integer sistema) {
    return props.perfil(sistema);   // se inyecta en lectores, escritores y validadores
}

@Configuration
@EnableConfigurationProperties({P107Properties.class, P107Rutas.class})
public class BitacoraJobConfig {

    @Bean
    Job bitacoraMovimientos(JobRepository repo,
                            Step inicio,             // 10000-INICIO-PROGRAMA
                            Step cargaCatalogos,     // 11000-CARGA-ESTRUCTURA + 12000-CARGA-CATALOGOS + 12900-OBTEN-TIT940
                            Step procesaMovimientos, // 20000: valida, aplica defaults, graba MOVIMIENTOS y CVETRAN
                            Step generaBitacora,     // 30000: SORT + impresión + MOVSXTERM (S028)
                            Step totalesPorClave,    // 35000: SORT CVETRAN + TOTCVETRAN + Mercator/INTELAR
                            Step rechazos) {         // 60000-GENERA-RECHAZOS
        return new JobBuilder("S151P107", repo)
                .start(inicio)
                .next(cargaCatalogos)
                .next(procesaMovimientos)
                .next(generaBitacora)
                .next(totalesPorClave)
                .next(rechazos)
                .build();
    }
}

